import { test, expect } from '@playwright/test';

test.describe('Mobile Hamburger Menu', () => {
  test.beforeEach(async ({ page }) => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });
    // Navigate to the application
    await page.goto('/');
    // Wait for page to be fully loaded
    await page.waitForLoadState('networkidle');
  });

  test('should open hamburger menu when clicking the menu button', async ({ page }) => {
    // Get the hamburger menu button
    const menuButton = page.getByRole('button', { name: /menu|hamburger|toggle/i });

    // Verify menu button is visible
    await expect(menuButton).toBeVisible();

    // Click the menu button
    await menuButton.click();

    // Verify the menu is now visible
    const navigationMenu = page.getByRole('navigation');
    await expect(navigationMenu).toBeVisible();

    // Verify menu items are displayed
    const menuItems = page.getByRole('link');
    const visibleItems = await menuItems.filter({ hasNot: page.locator('[style*="display: none"]') }).count();
    expect(visibleItems).toBeGreaterThan(0);
  });

  test('should close hamburger menu when clicking the menu button again', async ({ page }) => {
    // Get the hamburger menu button
    const menuButton = page.getByRole('button', { name: /menu|hamburger|toggle/i });

    // Open the menu
    await menuButton.click();

    // Verify menu is open
    const navigationMenu = page.getByRole('navigation');
    await expect(navigationMenu).toBeVisible();

    // Click the menu button again to close
    await menuButton.click();

    // Verify menu is closed (either hidden or not visible)
    await expect(navigationMenu).not.toBeVisible();
  });

  test('should close menu when clicking on a menu item', async ({ page }) => {
    // Get the hamburger menu button
    const menuButton = page.getByRole('button', { name: /menu|hamburger|toggle/i });

    // Open the menu
    await menuButton.click();

    // Verify menu is open
    const navigationMenu = page.getByRole('navigation');
    await expect(navigationMenu).toBeVisible();

    // Get the first menu link and click it
    const firstMenuLink = page.getByRole('link').first();
    await firstMenuLink.click();

    // Wait for navigation to complete
    await page.waitForLoadState('networkidle');

    // Verify menu is closed after clicking a link
    await expect(navigationMenu).not.toBeVisible();
  });

  test('should toggle menu state multiple times', async ({ page }) => {
    const menuButton = page.getByRole('button', { name: /menu|hamburger|toggle/i });
    const navigationMenu = page.getByRole('navigation');

    // First open
    await menuButton.click();
    await expect(navigationMenu).toBeVisible();

    // First close
    await menuButton.click();
    await expect(navigationMenu).not.toBeVisible();

    // Second open
    await menuButton.click();
    await expect(navigationMenu).toBeVisible();

    // Second close
    await menuButton.click();
    await expect(navigationMenu).not.toBeVisible();
  });

  test('should have accessible menu button', async ({ page }) => {
    const menuButton = page.getByRole('button', { name: /menu|hamburger|toggle/i });

    // Verify button is keyboard accessible
    await menuButton.focus();
    await expect(menuButton).toBeFocused();

    // Verify button can be activated with Enter key
    await menuButton.press('Enter');

    const navigationMenu = page.getByRole('navigation');
    await expect(navigationMenu).toBeVisible();
  });
});
